import type { Html } from "foldkit/html";

import * as FoldkitAccordion from "../../../foldkit/ui/accordion";

export {
  shadcnAccordionHeaderClasses,
  shadcnAccordionIconClasses,
  shadcnAccordionItemClasses,
  shadcnAccordionPanelClasses,
  shadcnAccordionRootClasses,
  shadcnAccordionTriggerClasses,
} from "./view";

export const includesValue = FoldkitAccordion.includesValue;
export const toggleValue = FoldkitAccordion.toggleValue;

export type AccordionStyle = FoldkitAccordion.AccordionStyle;

export type RootViewConfig = Readonly<{
  children: readonly Html[];
  openValues: readonly string[];
  className?: string | undefined;
  style?: AccordionStyle | undefined;
}>;

export type ItemViewConfig<ParentMessage> = Readonly<{
  value: string;
  openValues: readonly string[];
  onValueChange: ParentMessage;
  title: string;
  children: readonly Html[];
  disabled?: boolean | undefined;
  className?: string | undefined;
  style?: AccordionStyle | undefined;
  triggerClasses?: string | undefined;
  panelClasses?: string | undefined;
}>;

export const rootView = <ParentMessage>({
  children,
  openValues,
  className,
  style,
}: RootViewConfig): Html =>
  FoldkitAccordion.rootView<ParentMessage>({
    children,
    openValues,
    classes: className,
    style,
  });

export const itemView = <ParentMessage>({
  value,
  openValues,
  onValueChange,
  title,
  children,
  disabled,
  className,
  style,
  triggerClasses,
  panelClasses,
}: ItemViewConfig<ParentMessage>): Html =>
  FoldkitAccordion.itemView<ParentMessage>({
    value,
    openValues,
    onValueChange,
    title,
    children,
    disabled,
    classes: className,
    style,
    triggerClasses,
    panelClasses,
  });

export const shadcnAccordionRootClasses = "w-full max-w-2xl bg-white";

export const shadcnAccordionItemClasses =
  "border-b border-gray-200 data-[disabled]:opacity-50 data-[open]:bg-gray-50";

export const shadcnAccordionHeaderClasses = "m-0";

export const shadcnAccordionTriggerClasses =
  "group flex w-full cursor-pointer items-center justify-between gap-4 px-4 py-3 text-left text-sm font-medium text-gray-950 transition hover:bg-gray-50 focus-visible:outline-2 focus-visible:outline-inset focus-visible:outline-accent-600 data-[disabled]:cursor-not-allowed";

export const shadcnAccordionIconClasses =
  "text-gray-500 transition-transform group-data-[open]:rotate-45";

export const shadcnAccordionPanelClasses =
  "px-4 pb-4 text-sm leading-6 text-gray-600";

import { describe, expect, test } from "vitest";

import * as Accordion from "./index";

describe("shadcn Accordion registry view", () => {
  test("reuses the Foldkit Accordion view contract", () => {
    expect(Accordion.rootView).toBeTypeOf("function");
    expect(Accordion.itemView).toBeTypeOf("function");
    expect(Accordion.toggleValue(["one"], "one")).toEqual([]);
    expect(Accordion.shadcnAccordionRootClasses).not.toContain("border");
    expect(Accordion.shadcnAccordionItemClasses).toContain("border-b");
    expect(Accordion.shadcnAccordionTriggerClasses).toContain("font-medium");
  });
});
